cat >> test/queue.test.js <<'EOF'

test('keeps going after a job rejects or throws synchronously', async () => {
  const q = createQueue();
  const bad = q.add(async () => { throw new Error('boom'); });
  const sync = q.add(() => { throw new Error('sync'); });
  const plain = q.add(() => 42);
  await assert.rejects(bad, /boom/);
  await assert.rejects(sync, /sync/);
  assert.strictEqual(await plain, 42);
  await q.onIdle();
  assert.strictEqual(q.running, 0);
  assert.strictEqual(q.pending, 0);
});

test('onIdle waits for running jobs, not just pending ones', async () => {
  const q = createQueue({ concurrency: 2 });
  let done = false;
  q.add(async () => { await sleep(20); done = true; });
  await q.onIdle();
  assert.strictEqual(done, true);
  await q.onIdle(); // already idle: resolves immediately
});

test('onIdle resolves after a failing job', async () => {
  const q = createQueue();
  q.add(async () => { await sleep(5); throw new Error('x'); }).catch(() => {});
  await q.onIdle();
  assert.strictEqual(q.running, 0);
});

test('resume refills all free slots', async () => {
  const q = createQueue({ concurrency: 4 });
  q.pause();
  let active = 0;
  let peak = 0;
  const jobs = [];
  for (let i = 0; i < 8; i++) {
    jobs.push(q.add(async () => { active++; peak = Math.max(peak, active); await sleep(10); active--; }));
  }
  assert.strictEqual(q.running, 0);
  assert.strictEqual(q.pending, 8);
  q.resume();
  assert.strictEqual(q.running, 4);
  await Promise.all(jobs);
  assert.strictEqual(peak, 4);
});
EOF
